{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Sound-guided gatherings</title>
  <meta name="description" content="A playful, premium take on collective rest and tuned listening in {{CITY}}, {{STATE}}. Join a cohort, attend a curated evening, or book private sessions." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="8" fill="#1f2937"></rect><circle cx="24" cy="24" r="10" fill="#ffd166"></circle></svg>
      <div>
        <h1 class="business">{{BUSINESS_NAME}}</h1>
        <p class="tag">{{TAGLINE}}</p>
      </div>
    </div>
    <nav class="main-nav" aria-label="Main navigation">
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">One-on-One</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">Team</a>
      <a href="faq.html">FAQs</a>
      <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
      <a class="muted" href="contact.html">Say hi</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="hero-inner">
        <div class="hero-copy">
          <h2>Gather in tuned company — a cohort model for curious ears</h2>
          <p>Reserve a seat in a limited-cycle cohort where sound maps an hour of attention. Gentle rituals, thoughtful pacing, and a palette of resonances tuned to group intention.</p>
          <div class="hero-ctas">
            <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="ghost" href="events.html">See upcoming gatherings</a>
          </div>
          <p class="contact-line">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">email us</a>.</p>
        </div>
        <div class="hero-aside">
          <img src="assets/img/pattern.svg" alt="pattern background" class="pattern-art" aria-hidden="true" />
          <div class="quick-info">
            <div class="next-event">
              <h4>Next assembly</h4>
              <p><strong>Friday</strong> — Cohort: New Moon Session<br/>7:00pm • {{CITY}}, {{STATE}}</p>
              <a href="events.html" class="mini">Reserve a spot</a>
            </div>
            <div class="mixer-widget" id="mixer">
              <h4>Sound preference</h4>
              <p class="muted">Choose your edge — we’ll suggest programs.</p>
              <div class="mixer-controls">
                <button data-level="gentle" class="mix-btn active">Gentle</button>
                <button data-level="medium" class="mix-btn">Medium</button>
                <button data-level="intense" class="mix-btn">Intense</button>
              </div>
              <div class="mixer-recs">
                <h5>Recommended program</h5>
                <ul id="recs">
                  <li>Drift-Light: tonal lull and guided breath</li>
                  <li>Resonant Breath: layered bowls for softness</li>
                </ul>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="myth-truth">
      <div class="container">
        <h3>Myths & real talk</h3>
        <div class="grid-2">
          <div class="card myth">
            <h4>Myth</h4>
            <p>Sound baths are only for deep meditators.</p>
          </div>
          <div class="card truth">
            <h4>Truth</h4>
            <p>We design sound gatherings for a range of curiosities — from restful presence to vivid sensory recalibration.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="pillars">
      <div class="container">
        <h3>Foundations</h3>
        <div class="pillars-grid">
          <div class="pillar">
            <h4>Tuned Intent</h4>
            <p>Sessions are sequenced with intention—entrance, attunement, release.</p>
          </div>
          <div class="pillar">
            <h4>Human-scaled cohorts</h4>
            <p>Small, steady groups that build familiarity across a cycle.</p>
          </div>
          <div class="pillar">
            <h4>Transparent safety</h4>
            <p>We list contraindications and offer alternatives for comfort.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="case-notes">
      <div class="container">
        <h3>Proof gallery</h3>
        <p class="muted">Rotating testimonials and badges from partners and press.</p>
        <div class="proof-wrap">
          <div class="testimonials" id="testimonials" aria-live="polite">
            <blockquote class="quote" data-index="0">“A delicate itinerary of sound—left me calmer and oddly more alert.” <cite>— S. (attendee)</cite></blockquote>
            <blockquote class="quote" data-index="1">“We brought a team for a restorative workshop; the guidance was exact and generous.” <cite>— A. (organizer)</cite></blockquote>
            <blockquote class="quote" data-index="2">“I booked a private session for post-op recovery and was amazed by the care.” <cite>— J. (client)</cite></blockquote>
          </div>
          <div class="badges" id="badges">
            <div class="badge" data-tip="Featured in Calm Weekly">CalmWeekly</div>
            <div class="badge" data-tip="Partner: MindfulWork">MindfulWork</div>
            <div class="badge" data-tip="Certified facilitator network">FacNet</div>
          </div>
        </div>
      </div>
    </section>

    <section class="faq-section">
      <div class="container">
        <h3>Quick questions</h3>
        <details>
          <summary>What should I bring?</summary>
          <p>Comfortable layers, a mat or blanket if you prefer, and an open curiosity. We provide bolsters and blankets upon request.</p>
        </details>
        <details>
          <summary>Who should avoid sessions?</summary>
          <p class="warning">Contraindications: pregnancy (first trimester without physician clearance), uncontrolled epilepsy, recent head injury, active severe psychiatric events. If you have medical concerns, consult your provider and contact us prior to attending.</p>
        </details>
      </div>
    </section>

    <section class="cta-invite">
      <div class="container">
        <h3>Ready to reserve a spot?</h3>
        <p>Join a cohort, book a private hour, or ask us about group rates.
        </p>
        <div class="cta-row">
          <a class="primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="ghost" href="pricing.html">See plans</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Cohort model, curated resonance. <a href="privacy.html">Privacy</a></p>
      <p>Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
