{"path":"assets/css/styles.css","content":"/* Minimal reset */
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.4;color:#0f172a;margin:0;background:#fbfbfd}
.container{max-width:1000px;margin:0 auto;padding:24px}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;border-bottom:1px solid rgba(15,23,42,0.06);background:#fff}
.brand{display:flex;align-items:center;gap:12px}
.brand .logo{flex:0 0 48px}
.business{font-size:14px;margin:0}
.tag{font-size:12px;margin:0;color:#6b7280}
.main-nav a{margin-left:14px;text-decoration:none;color:#111827;font-size:14px}
.main-nav a.cta{background:#0ea5a4;color:#fff;padding:8px 12px;border-radius:8px}
.main-nav a.muted{color:#6b7280;margin-left:8px}
.hero{background:linear-gradient(180deg,#fff 0%, #f8fafc 100%);padding:40px 0}
.hero-inner{display:flex;gap:32px;align-items:flex-start}
.hero-copy{flex:1;padding:12px}
.hero-copy h2{font-size:28px;margin:0 0 12px;color:#0f172a}
.hero-copy p{margin:0 0 16px;color:#374151}
.hero-ctas a.primary{background:#0ea5a4;color:#fff;padding:10px 16px;border-radius:10px;text-decoration:none;margin-right:8px}
.hero-ctas a.ghost{background:transparent;border:1px solid #e5e7eb;padding:8px 12px;border-radius:10px;text-decoration:none;color:#0f172a}
.contact-line{font-size:13px;color:#6b7280;margin-top:10px}
.hero-aside{width:320px;position:relative}
.pattern-art{width:100%;height:auto;display:block;border-radius:12px}
.quick-info{position:absolute;top:12px;left:12px;right:12px;background:rgba(255,255,255,0.92);padding:12px;border-radius:10px;box-shadow:0 6px 18px rgba(2,6,23,0.06)}
.next-event h4{margin:0 0 6px;font-size:13px}
.next-event p{margin:0 0 8px;color:#374151}
.next-event a.mini{font-size:13px;color:#0ea5a4;text-decoration:none}
.mixer-widget h4{margin:12px 0 6px;font-size:14px}
.mixer-controls{display:flex;gap:8px}
.mix-btn{padding:6px 10px;border-radius:8px;border:1px solid #e6eef0;background:#fff;cursor:pointer}
.mix-btn.active{background:#e6fffb;border-color:#0ea5a4}
.mixer-recs h5{margin:8px 0 6px;font-size:13px}
.mixer-recs ul{margin:0;padding-left:18px;color:#374151}
.myth-truth{padding:28px 0;background:#fff}
.grid-2{display:flex;gap:18px}
.card{padding:16px;border-radius:10px;background:#f8fafc}
.card.myth{background:#fff7ed}
.card.truth{background:#ecfeff}
.pillars{padding:28px 0}
.pillars-grid{display:flex;gap:16px}
.pillar{flex:1;background:#fff;padding:16px;border-radius:10px;border:1px solid #eef2f7}
.case-notes{padding:28px 0;background:#fff}
.proof-wrap{display:flex;gap:18px;align-items:flex-start}
.testimonials{flex:1;min-height:110px}
.quote{display:none;font-style:italic;background:#f8fafc;padding:14px;border-radius:10px}
.quote.active{display:block}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:#111827;color:#fff;padding:8px 10px;border-radius:8px;font-weight:600;cursor:default;position:relative}
.badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:110%;top:50%;transform:translateY(-50%);white-space:nowrap;background:#0f172a;color:#fff;padding:8px 10px;border-radius:8px;font-size:13px}
.faq-section{padding:28px 0}
details summary{cursor:pointer;padding:10px;background:#fff;border-radius:8px;border:1px solid #eef2f7}
details p{padding:10px;margin:8px 0}
.warning{color:#991b1b}
.cta-invite{padding:40px 0;background:linear-gradient(180deg,#f7f9fc,#fff)}
.cta-row{margin-top:12px}
.primary.large{padding:12px 18px}
.site-footer{padding:18px 24px;border-top:1px solid rgba(15,23,42,0.06);background:#fff}
@media(max-width:860px){
  .hero-inner{flex-direction:column}
  .hero-aside{width:100%}
  .grid-2{flex-direction:column}
  .pillars-grid{flex-direction:column}
  .proof-wrap{flex-direction:column}
  .badges{flex-direction:row}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Set year in footer
  document.getElementById('year').textContent = new Date().getFullYear();

  // Mixer logic
  var mixButtons = document.querySelectorAll('.mix-btn');
  var recsEl = document.getElementById('recs');

  var programs = {
    gentle: ['Drift-Light: tonal lull and guided breath','Soft Arc: single-bowl resonance and micro-guidance'],
    medium: ['Resonant Weave: layered bowls and vocal tones','Evening Loom: pacing for release and wakeful rest'],
    intense: ['Deep Field: sustained harmonic immersion','Foundry: dense overtones for somatic work']
  };

  function setActiveLevel(level){
    mixButtons.forEach(function(btn){
      btn.classList.toggle('active', btn.getAttribute('data-level')===level);
    });
    // Update recs
    recsEl.innerHTML = '';
    programs[level].forEach(function(p){
      var li = document.createElement('li'); li.textContent = p; recsEl.appendChild(li);
    });
  }

  mixButtons.forEach(function(btn){
    btn.addEventListener('click', function(){
      setActiveLevel(this.getAttribute('data-level'));
    });
  });

  // default
  setActiveLevel('gentle');

  // Testimonials rotation
  var quotes = Array.prototype.slice.call(document.querySelectorAll('.quote'));
  var current = 0;
  function showQuote(i){
    quotes.forEach(function(q){ q.classList.remove('active'); });
    quotes[i].classList.add('active');
  }
  showQuote(0);
  setInterval(function(){
    current = (current + 1) % quotes.length;
    showQuote(current);
  },5000);

  // Badges tooltips (simple keyboard access)
  var badges = document.querySelectorAll('.badge');
  badges.forEach(function(b){
    b.setAttribute('tabindex','0');
    b.addEventListener('focus',function(){
      var tip = b.getAttribute('data-tip');
      var el = document.createElement('div');
      el.className = 'badge-tip';
      el.textContent = tip;
      el.style.position = 'absolute';
      el.style.left = '110%';
      el.style.top = '50%';
      el.style.transform = 'translateY(-50%)';
      el.style.padding = '8px 10px';
      el.style.background = '#0f172a';
      el.style.color = '#fff';
      el.style.borderRadius = '8px';
      el.style.fontSize = '13px';
      el.dataset.tmp = '1';
      b.appendChild(el);
    });
    b.addEventListener('blur',function(){
      var tmp = b.querySelector('[data-tmp]');
      if(tmp) b.removeChild(tmp);
    });
  });

  // Accessibility: allow arrow keys to change mixer
  document.getElementById('mixer').addEventListener('keydown', function(e){
    var key = e.key;
    if(key==='ArrowLeft' || key==='ArrowRight'){
      var activeIndex = Array.prototype.findIndex.call(mixButtons, function(b){ return b.classList.contains('active'); });
      if(activeIndex === -1) activeIndex = 0;
      if(key==='ArrowLeft') activeIndex = Math.max(0, activeIndex-1);
      if(key==='ArrowRight') activeIndex = Math.min(mixButtons.length-1, activeIndex+1);
      var level = mixButtons[activeIndex].getAttribute('data-level');
      setActiveLevel(level);
    }
  });

  // Small utility: if coming from book CTA, focus mixer
  if(location.hash === '#tune'){
    mixButtons[0].focus();
  }
})();
"} 
